function co_sales_edit_page() {
	if ( ! current_user_can( 'edit_posts' ) ) return; $id = absint( $_GET['document'] ?? 0 ); $document = $id ? get_post( $id ) : null; if ( $id && ( ! $document || 'sales_document' !== $document->post_type ) ) wp_die( 'Document not found.' ); $type = $document ? co_sales_meta( $id, 'document_type', 'quotation' ) : 'quotation'; $clients = co_sales_clients(); $projects = co_crm_projects(); $issuers = co_sales_issuers(); $prefill_project_id = absint( $_GET['project'] ?? 0 ); $prefill_project = 'client_project' === get_post_type( $prefill_project_id ) ? get_post( $prefill_project_id ) : null; $default_body = $prefill_project ? co_crm_project_brief( $prefill_project_id ) : ''; if ( ! $default_body ) $default_body = co_sales_default_concept(); $default_subtotal = $prefill_project ? co_crm_meta( $prefill_project_id, 'net_total' ) : ''; $schedule_text = $document ? co_sales_meta( $id, 'payment_schedule_text' ) : "30|ยืนยันการจัดจ้างและส่งมอบ Working Timeline\n30|Wireframe และออกแบบเว็บไซต์แล้วเสร็จ\n30|พัฒนาระบบเว็บไซต์แล้วเสร็จ\n10|ส่งมอบงานและคู่มือการใช้งาน"; co_sales_assets(); ?>
	<div class="sales-wrap"><header class="sales-edit-head"><div><a href="<?php echo esc_url( admin_url( 'admin.php?page=co-sales-documents' ) ); ?>">← Documents</a><small><?php echo esc_html( strtoupper( $type ) ); ?></small><h1><?php echo $document ? esc_html( co_sales_meta( $id, 'number' ) ) : 'New quotation'; ?></h1></div><?php if ( $document ) : ?><div><a class="sales-btn light" target="_blank" href="<?php echo esc_url( admin_url( 'admin.php?page=co-sales-preview&document=' . $id ) ); ?>">Preview / PDF ↗</a><?php if ( 'quotation' === $type ) : $schedule = (array) co_sales_meta( $id, 'payment_schedule', array() ); ?><div class="sales-derive"><?php foreach ( $schedule as $index => $row ) : ?><a href="<?php echo esc_url( wp_nonce_url( admin_url( 'admin-post.php?action=co_sales_derive_document&source=' . $id . '&installment=' . ( $index + 1 ) ), 'co_sales_derive_' . $id ) ); ?>">Create invoice <?php echo $index + 1; ?></a><?php endforeach; ?></div><?php elseif ( 'invoice' === $type ) : ?><a class="sales-btn" data-sales-confirm="Create a receipt from this invoice?" href="<?php echo esc_url( wp_nonce_url( admin_url( 'admin-post.php?action=co_sales_derive_document&source=' . $id ), 'co_sales_derive_' . $id ) ); ?>">Create receipt</a><?php endif; ?></div><?php endif; ?></header><form class="sales-form sales-document-form" method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><?php wp_nonce_field( 'co_sales_document' ); ?><input type="hidden" name="action" value="co_sales_save_document"><input type="hidden" name="document_id" value="<?php echo $id; ?>"><input type="hidden" name="document_type" value="<?php echo esc_attr( $type ); ?>"><input type="hidden" name="source_document_id" value="<?php echo absint( $document ? co_sales_meta( $id, 'source_document_id' ) : 0 ); ?>"><section class="sales-panel"><h2>Document information</h2><div class="sales-grid"><label>Client *<select required id="sales-client" name="client_id"><option value="">Select client</option><?php foreach ( $clients as $client ) : ?><option value="<?php echo $client->ID; ?>" <?php selected( $document ? co_sales_meta( $id, 'client_id' ) : 0, $client->ID ); ?>><?php echo esc_html( $client->post_title ); ?></option><?php endforeach; ?></select></label><label>Project<select id="sales-project" name="project_id"><option value="">No linked project</option><?php foreach ( $projects as $project ) : ?><option value="<?php echo $project->ID; ?>" <?php selected( $document ? co_sales_meta( $id, 'project_id' ) : $prefill_project_id, $project->ID ); ?>><?php echo esc_html( co_crm_meta( $project->ID, 'company', 'Client' ) . ' — ' . $project->post_title ); ?></option><?php endforeach; ?></select></label><label>Issuer *<select required name="issuer_id"><?php foreach ( $issuers as $issuer ) : ?><option value="<?php echo esc_attr( $issuer['id'] ); ?>" <?php selected( $document ? co_sales_meta( $id, 'issuer_id' ) : '', $issuer['id'] ); ?>><?php echo esc_html( $issuer['name'] ?: 'Configure issuer' ); ?></option><?php endforeach; ?></select></label><label>Issue date<input required type="date" name="issue_date" value="<?php echo esc_attr( $document ? co_sales_meta( $id, 'issue_date' ) : wp_date( 'Y-m-d' ) ); ?>"></label><label>Status<select name="document_status"><?php foreach ( co_sales_statuses() as $key => $label ) : ?><option value="<?php echo esc_attr( $key ); ?>" <?php selected( $document ? co_sales_meta( $id, 'status', 'draft' ) : 'draft', $key ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></label><label>Installment<input min="0" type="number" name="installment_no" value="<?php echo absint( $document ? co_sales_meta( $id, 'installment_no' ) : 0 ); ?>"></label></div></section><section class="sales-panel"><h2>Scope and pricing</h2><label>Document / installment title<input name="document_title" value="<?php echo esc_attr( $document ? co_sales_meta( $id, 'title' ) : ( $prefill_project ? $prefill_project->post_title : 'Website Design & Development' ) ); ?>"></label><label>Project concept and tasks<textarea name="document_body" rows="24"><?php echo esc_textarea( $document ? co_sales_meta( $id, 'body' ) : $default_body ); ?></textarea></label><div class="sales-grid finance"><label>Project / installment value<input required min="0" step=".01" type="number" name="subtotal" value="<?php echo esc_attr( $document ? co_sales_document_total( $id ) : $default_subtotal ); ?>"></label><label>WHT rate (%)<input min="0" step=".01" type="number" name="wht_rate" value="<?php echo esc_attr( $document ? co_sales_meta( $id, 'wht_rate', 3 ) : 3 ); ?>"></label><div><small>WHT amount</small><strong>฿<span data-sales-wht>0.00</span></strong></div><div><small>Grand total</small><strong>฿<span data-sales-total>0.00</span></strong></div></div><?php if ( 'quotation' === $type ) : ?><label>Payment schedule <small>หนึ่งงวดต่อหนึ่งบรรทัด: เปอร์เซ็นต์|รายละเอียด</small><textarea name="payment_schedule" rows="6"><?php echo esc_textarea( $schedule_text ); ?></textarea></label><?php else : ?><input type="hidden" name="payment_schedule" value=""><?php endif; ?><label>Notes<textarea name="notes" rows="4"><?php echo esc_textarea( $document ? co_sales_meta( $id, 'notes' ) : '' ); ?></textarea></label></section><div class="sales-actions"><a class="sales-btn light" href="<?php echo esc_url( admin_url( 'admin.php?page=co-sales-documents' ) ); ?>">Cancel</a><button class="sales-btn" type="submit">Save document</button></div></form></div>
<?php }

function co_sales_preview_page() {
	if ( ! current_user_can( 'edit_posts' ) ) return; $id = absint( $_GET['document'] ?? 0 ); $document = get_post( $id ); if ( ! $document || 'sales_document' !== $document->post_type ) wp_die( 'Document not found.' ); $type = co_sales_meta( $id, 'document_type' ); $client = (array) co_sales_meta( $id, 'client_snapshot', array() ); $issuer = (array) co_sales_meta( $id, 'issuer_snapshot', array() ); $signature = ! empty( $issuer['signature_id'] ) ? wp_get_attachment_image_url( $issuer['signature_id'], 'medium' ) : ''; co_sales_assets(); ?>
	<div class="sales-preview-toolbar"><a href="<?php echo esc_url( admin_url( 'admin.php?page=co-sales-edit&document=' . $id ) ); ?>">← Edit document</a><button class="sales-btn" onclick="window.print()">Print / Save PDF</button></div><main class="sales-paper"><header><div><h1><?php echo esc_html( array( 'quotation' => 'ใบเสนอราคา', 'invoice' => 'ใบแจ้งหนี้', 'receipt' => 'ใบเสร็จรับเงิน' )[$type] ?? 'เอกสาร' ); ?></h1><h2><?php echo esc_html( co_sales_types()[$type] ?? 'Document' ); ?></h2></div><dl><div><dt>เลขที่ / No.</dt><dd><?php echo esc_html( co_sales_meta( $id, 'number' ) ); ?></dd></div><div><dt>วันที่ / Issue</dt><dd><?php echo esc_html( co_sales_date( co_sales_meta( $id, 'issue_date' ) ) ); ?></dd></div></dl></header><section class="sales-party"><div><b>ลูกค้า / Customer</b><strong><?php echo esc_html( $client['name'] ?? '' ); ?></strong><p><?php echo nl2br( esc_html( $client['address'] ?? '' ) ); ?></p><p><b>เลขผู้เสียภาษี / Tax ID</b> <?php echo esc_html( $client['tax_id'] ?? '' ); ?></p><p><b>ผู้ติดต่อ / Attention</b> <?php echo esc_html( $client['contact_name'] ?? '' ); ?><?php echo ! empty( $client['phone'] ) ? ' · ' . esc_html( $client['phone'] ) : ''; ?></p></div><div><b>ผู้ออก / Issuer</b><strong><?php echo esc_html( $issuer['name'] ?? '' ); ?></strong><p><?php echo nl2br( esc_html( $issuer['address'] ?? '' ) ); ?></p><p><b>เลขผู้เสียภาษี / Tax ID</b> <?php echo esc_html( $issuer['tax_id'] ?? '' ); ?></p><p><?php echo esc_html( $issuer['phone'] ?? '' ); ?> · <?php echo esc_html( $issuer['email'] ?? '' ); ?></p></div></section><section class="sales-paper-table"><div class="head"><span>รหัส<br>ID no.</span><span>คำอธิบาย<br>Description</span><span>มูลค่าก่อนหัก<br>Pre-WHT Amount</span></div><div class="body"><span><?php echo $type === 'quotation' ? 'QO' : ( $type === 'invoice' ? 'IV' : 'RC' ); ?></span><div><h3><?php echo esc_html( co_sales_meta( $id, 'title' ) ); ?></h3><div class="sales-document-copy"><?php echo nl2br( esc_html( co_sales_meta( $id, 'body' ) ) ); ?></div><?php $schedule = (array) co_sales_meta( $id, 'payment_schedule', array() ); if ( $schedule ) : ?><h3>Terms of Payment</h3><ol><?php foreach ( $schedule as $row ) : ?><li><b><?php echo esc_html( co_sales_money( $row['percent'] ) ); ?>%</b> <?php echo esc_html( $row['description'] ); ?></li><?php endforeach; ?></ol><?php endif; ?></div><strong><?php echo esc_html( co_sales_money( co_sales_document_total( $id ) ) ); ?></strong></div></section><footer><div class="sales-bank"><?php if ( in_array( $type, array( 'invoice','receipt' ), true ) ) : ?><b>การชำระเงิน / Payment</b><p><?php echo nl2br( esc_html( $issuer['bank'] ?? '' ) ); ?></p><?php endif; ?></div><div class="sales-totals"><p><span>ราคาสุทธิ / Pre-WHT Amount</span><strong><?php echo esc_html( co_sales_money( co_sales_document_total( $id ) ) ); ?></strong></p><p><span>หัก ณ ที่จ่าย <?php echo esc_html( co_sales_meta( $id, 'wht_rate', 3 ) ); ?>% / WHT</span><strong><?php echo esc_html( co_sales_money( co_sales_wht( $id ) ) ); ?></strong></p><p><span>จำนวนเงินรวมทั้งสิ้น / Grand Total</span><strong><?php echo esc_html( co_sales_money( co_sales_grand_total( $id ) ) ); ?></strong></p></div></footer><section class="sales-signatures"><div><b>อนุมัติโดย / Approved by</b><?php if ( $signature ) : ?><img src="<?php echo esc_url( $signature ); ?>" alt="Signature"><?php endif; ?><p>วันที่ / Date <?php echo esc_html( co_sales_date( co_sales_meta( $id, 'issue_date' ) ) ); ?></p></div><div><b>ยอมรับเอกสาร / Accepted by</b><span></span><p>วันที่ / Date ........................</p></div></section></main>
<?php }

function co_sales_render_project_documents( $project_id ) {
	$documents = co_sales_documents( $project_id ); ?><section class="crm-drawer-section"><div class="crm-section-heading"><div><h3>Sales documents</h3><p>Quotations, invoices and receipts for this project.</p></div><a class="crm-btn" href="<?php echo esc_url( admin_url( 'admin.php?page=co-sales-edit&project=' . $project_id ) ); ?>">+ Quotation</a></div><div class="sales-project-docs"><?php if ( $documents ) : foreach ( $documents as $document ) : ?><a href="<?php echo esc_url( admin_url( 'admin.php?page=co-sales-edit&document=' . $document->ID ) ); ?>"><span><?php echo esc_html( co_sales_meta( $document->ID, 'number' ) ); ?><small><?php echo esc_html( co_sales_types()[co_sales_meta( $document->ID, 'document_type' )] ?? 'Document' ); ?></small></span><strong>฿<?php echo esc_html( co_sales_money( co_sales_grand_total( $document->ID ) ) ); ?></strong></a><?php endforeach; else : ?><p>No sales documents yet.</p><?php endif; ?></div></section><?php
}
